import { describe, expect, it } from "vitest";
import rawRender from "@/data/venue_render.json";
import {
  displayMass,
  linearPos,
  nodePhase,
  renderRowAsVenueRow,
  type RenderDoc,
  type RenderRow,
} from "@/state/atlas";

/**
 * Render-seed integrity (the venueRender analog of the contractFacts
 * staleness gate): the artifact is GENERATED by tools/dys_venue_render.py —
 * these pins catch hand-edits and upstream drift. Spot values are computed
 * from the s32 atlas by the generator; if they change, REGENERATE, never
 * hand-fix.
 */

const doc = rawRender as unknown as RenderDoc;
const rows = doc.venues;

const ILLINOIS: RenderRow | undefined = rows.find((r) => r.a === "0xd127839b83cbf537c29b7d268c135f745a0da2e8");
const OZYMANDIAS: RenderRow | undefined = rows.find((r) => r.a === "0xe41165bfd2c38a682289b2783d1e6e2e39e3766a");

describe("venue render seed integrity", () => {
  it("carries the s32 venues (the count moves with regens — session-70: 940), unique, in range", () => {
    expect(doc._meta.count).toEqual(rows.length);
    expect(rows.length).toBeGreaterThanOrEqual(917);
    expect(new Set(rows.map((r) => r.a)).size).toEqual(rows.length);
    for (const r of rows) {
      expect(r.lon).toBeGreaterThanOrEqual(-180);
      expect(r.lon).toBeLessThanOrEqual(180);
      expect(r.lat).toBeGreaterThanOrEqual(-90);
      expect(r.lat).toBeLessThanOrEqual(90);
      expect(r.band).toBeGreaterThanOrEqual(0);
      expect(r.band).toBeLessThanOrEqual(89);
      expect(r.f).toBeGreaterThanOrEqual(-1);
      expect(r.f).toBeLessThanOrEqual(1);
      expect(r.w).toMatch(/^\d+$/);
    }
  });

  it("spot: Illinois (north, band 86) — lon 86*4 + 2*f wrapped, lat exact-pole scale", () => {
    // 344 - 2*0.824028571691 = 342.351942857 -> wrap -> -17.648057143
    // lat uses the EXACT pole (Meridians[88]//333, kb §9) — the session-48
    // fix of the predecessor's 1.2e72 approximation (was -3.420959)
    expect(ILLINOIS).toBeDefined();
    expect(ILLINOIS!.lon).toBeCloseTo(-17.648057, 5);
    expect(ILLINOIS!.lat).toBeCloseTo(-3.469548, 5);
    expect(ILLINOIS!.ln).toBeCloseTo(0.038550531, 9);
    expect(ILLINOIS!.south).toBe(false);
  });

  it("spot: Ozymandias (south-flip, band 68) — mirrored latitude, atlas fold fraction", () => {
    // the old QingMap's posInBand formula would put this at -89.62 (a -2deg
    // shift); the s32-exact atlas convention is what ships. lat/ln exact-pole
    expect(OZYMANDIAS).toBeDefined();
    expect(OZYMANDIAS!.f).toBeCloseTo(0.19014520346011593, 9);
    expect(OZYMANDIAS!.lon).toBeCloseTo(68 * 4 + 2 * 0.19014520346011593 - 360, 5);
    expect(OZYMANDIAS!.lat).toBeCloseTo(-34.737137, 5);
    expect(OZYMANDIAS!.ln).toBeCloseTo(0.385968187, 9);
    expect(OZYMANDIAS!.south).toBe(true);
  });

  it("the canonical ln is |lat|/90 within tolerance for every venue (framing consistency)", () => {
    for (const r of rows) {
      expect(r.ln).toBeGreaterThanOrEqual(0);
      expect(r.ln).toBeLessThanOrEqual(1);
      expect(Math.abs(r.ln - Math.abs(r.lat) / 90)).toBeLessThan(1e-4);
    }
  });

  it("marks exactly one sys venue — the first QING (Phobos) from config", () => {
    const sys = rows.filter((r) => r.sys);
    expect(sys).toHaveLength(1);
    expect(sys[0]!.a).toEqual("0xb0ba7d36b7f0505879179ece7401f24eb653c6e1");
  });
});

describe("atlas pure helpers", () => {
  it("renderRowAsVenueRow maps onto the store's seed shape (lat = folded f)", () => {
    const v = renderRowAsVenueRow(ILLINOIS!);
    expect(v).toEqual({
      a: ILLINOIS!.a,
      n: ILLINOIS!.n,
      s: ILLINOIS!.s,
      lat: ILLINOIS!.f,
      band: 86,
      blk: 22813947,
    });
  });

  it("display mass is the old entropySim idiom — deterministic, Phobos heavy", () => {
    expect(displayMass(ILLINOIS!)).toEqual((parseInt(ILLINOIS!.a.slice(-4), 16) % 30) + 10);
    expect(displayMass(rows.find((r) => r.sys)!)).toEqual(100);
    expect(displayMass(ILLINOIS!)).toEqual(displayMass(ILLINOIS!));
  });

  it("node phases are deterministic and in [0, 2π)", () => {
    const p = nodePhase(ILLINOIS!);
    expect(p).toBeGreaterThanOrEqual(0);
    expect(p).toBeLessThan(Math.PI * 2);
    expect(nodePhase(ILLINOIS!)).toEqual(p);
  });

  it("LINEAR projection folds waat onto the flat grid (old alt coordinates)", () => {
    const w = BigInt(ILLINOIS!.w);
    const p = linearPos(ILLINOIS!.w);
    expect(p.lat).toEqual(Number((w % 180n)) - 90);
    expect(p.lon).toEqual(Number((w / 180n) % 360n) - 180);
  });

  it("LINEAR projection survives a malformed waat", () => {
    expect(linearPos("not-a-number")).toEqual({ lon: 0, lat: 0 });
  });
});
